INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('host-census-false-positive', 'the host census files healthy hosts as broken and keeps owner-decided lapsed domains in the fleet count, so HOST-CENSUS-BROKEN-1 never closes on a true measurement', 'host_census.py judged each host on one 15 s attempt, read an unfollowed redirect as ok, and had no notion of a registration the owner chose to let lapse (human_actions 65 and 73, DEFAULT-ADOPTED-1)', 'HOST-CENSUS-FP-1: two retries with a 30 s timeout, redirect-loop for an unfollowed redirect, and an owner_bound list (registrar-reported lapse plus a standing IDENTITY-BOUND card naming the host) outside public_hosts_broken', 'the latest host-census row records retries >= 1 and an owner_bound object', 'fm-host-census-false-positive', '2026-10-13', 2130, 'a runner network stall during the census, or a spare domain the owner lets lapse', 'HOST-CENSUS-BROKEN-1 names hosts that answer 200, 301 or 410 to any later probe, or only hosts an owner card already decided', 'the public_hosts_broken metric and every closure decision read from HOST-CENSUS-BROKEN-1');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, requires_container) VALUES
 ('fm-host-census-false-positive', NULL, 'HOST-CENSUS-FP-1', 'failure-mode detector', 'SELECT ''1'' AS expected, CASE WHEN (SELECT COALESCE(json_extract(meta, ''$.retries''), 0) FROM cloud_ops_events WHERE kind = ''host-census'' ORDER BY ts DESC LIMIT 1) >= 1 AND (SELECT json_type(meta, ''$.owner_bound'') FROM cloud_ops_events WHERE kind = ''host-census'' ORDER BY ts DESC LIMIT 1) = ''object'' THEN ''1'' ELSE ''0'' END AS observed', 'd1-query', 3, 'host-census', 1, 'active', 'failure-mode', 45000, 5, 0);
